
// Input-only Boolean coefficient algebra. Square-free ANF distributes through
// small products; oversized pure-input functions become immutable input atoms.
// Each atom retains an exact semantic operator/definition for validation.
#[derive(Clone,Copy)]struct Expr{kind:u8,a:u32,b:u32,random:bool}
#[derive(Clone,PartialEq,Eq,Hash)]struct InputPoly{constant:bool,atoms:Vec<u32>}
struct Dag{nodes:Vec<Expr>,polys:Vec<std::sync::Arc<InputPoly>>,monomials:Vec<std::sync::Arc<[u32]>>,mono_cache:std::collections::HashMap<std::sync::Arc<[u32]>,u32>,poly_cache:std::collections::HashMap<std::sync::Arc<InputPoly>,u32>,large_defs:Vec<std::sync::Arc<[u32]>>,large_cache:std::collections::HashMap<std::sync::Arc<[u32]>,u32>,products:std::collections::HashMap<(Vec<u32>,Vec<u32>),u32>,mono_products:std::collections::HashMap<(u32,u32),u32>,xor_edges:std::collections::HashMap<(u32,u32),u32>,parents:Vec<u32>}
impl Dag{
 fn new()->Self{let p0=std::sync::Arc::new(InputPoly{constant:false,atoms:Vec::new()});let p1=std::sync::Arc::new(InputPoly{constant:true,atoms:Vec::new()});let mut cache=std::collections::HashMap::new();cache.insert(p0.clone(),0);cache.insert(p1.clone(),1);Self{nodes:vec![Expr{kind:0,a:0,b:0,random:false},Expr{kind:1,a:0,b:0,random:false}],polys:vec![p0,p1],monomials:Vec::new(),mono_cache:std::collections::HashMap::new(),poly_cache:cache,large_defs:Vec::new(),large_cache:std::collections::HashMap::new(),products:std::collections::HashMap::new(),mono_products:std::collections::HashMap::new(),xor_edges:std::collections::HashMap::new(),parents:vec![0,1]}}
 fn find(&self,mut id:u32)->u32{while self.parents[id as usize]!=id{id=self.parents[id as usize];}id}
 fn unite(&mut self,a:u32,b:u32){let a=self.find(a);let b=self.find(b);if a!=b{self.parents[a.max(b)as usize]=a.min(b);}}
 fn mono(&mut self,key:Vec<u32>)->u32{if let Some(id)=self.mono_cache.get(key.as_slice()){return *id;}let id=self.monomials.len().try_into().unwrap();let key:std::sync::Arc<[u32]>=key.into();self.monomials.push(key.clone());self.mono_cache.insert(key,id);id}
 fn atomic(&mut self,kind:u8,a:u32,b:u32,random:bool)->u32{let id=self.nodes.len().try_into().unwrap();let mono=self.mono(vec![id]);let poly=std::sync::Arc::new(InputPoly{constant:false,atoms:vec![mono]});self.nodes.push(Expr{kind,a:if kind==2{id}else{a},b,random});self.polys.push(poly.clone());self.poly_cache.insert(poly,id);self.parents.push(id);id}
 fn variable(&mut self,random:bool)->u32{self.atomic(2,0,0,random)}
 fn complementary(&self,a:u32,b:u32)->bool{let a=self.find(a);let b=self.find(b);self.polys[a as usize].constant!=self.polys[b as usize].constant&&self.polys[a as usize].atoms==self.polys[b as usize].atoms}
 fn has_and_factor(&self,expr:u32,factor:u32)->bool{let expr=self.find(expr);let factor=self.find(factor);let n=self.nodes[expr as usize];if n.kind==4&&(self.find(n.a)==factor||self.find(n.b)==factor){return true;}let f=&self.polys[factor as usize];let e=&self.polys[expr as usize];if f.constant||f.atoms.len()!=1||e.constant||e.atoms.is_empty(){return false;}let wanted=&self.monomials[f.atoms[0]as usize];e.atoms.iter().all(|id|wanted.iter().all(|v|self.monomials[*id as usize].binary_search(v).is_ok()))}
 fn merge_xor(a:&[u32],b:&[u32])->Vec<u32>{let mut out=Vec::with_capacity(a.len()+b.len());let(mut i,mut j)=(0,0);while i<a.len()||j<b.len(){if i<a.len()&&(j==b.len()||a[i]<b[j]){out.push(a[i]);i+=1;}else if j<b.len()&&(i==a.len()||b[j]<a[i]){out.push(b[j]);j+=1;}else{i+=1;j+=1;}}out}
 fn unfold(&self,atoms:Vec<u32>)->Vec<u32>{if atoms.len()>16{return atoms;}let def=|id:u32|{let m=&self.monomials[id as usize];if m.len()!=1{return None;}let n=self.nodes[m[0]as usize];if n.kind==7{Some(&self.large_defs[n.a as usize])}else{None}};let count:usize=atoms.iter().map(|id|def(*id).map_or(1,|x|x.len())).sum();if count>512||!atoms.iter().any(|id|def(*id).is_some()){return atoms;}let mut out=std::collections::BTreeSet::new();for id in atoms{if let Some(d)=def(id){for v in d.iter(){if !out.insert(*v){out.remove(v);}}}else if !out.insert(id){out.remove(&id);}}out.into_iter().collect()}
 fn reduce(&mut self,constant:bool,atoms:Vec<u32>,kind:u8,a:u32,b:u32)->u32{let atoms=self.unfold(atoms);if atoms.len()>16{let id=if let Some(id)=self.large_cache.get(atoms.as_slice()){*id}else{let index=self.large_defs.len().try_into().unwrap();let next=self.nodes.len();assert!(atoms.iter().all(|m|self.monomials[*m as usize].iter().all(|v|(*v as usize)<next)));let random=atoms.iter().any(|m|self.monomials[*m as usize].iter().any(|v|self.nodes[*v as usize].random));let def:std::sync::Arc<[u32]>=atoms.into();self.large_defs.push(def.clone());let id=self.atomic(7,index,0,random);if self.large_cache.len()>=200000{self.large_cache.clear();}self.large_cache.insert(def,id);id};return if constant{self.not(id)}else{id};}let poly=std::sync::Arc::new(InputPoly{constant,atoms});if let Some(id)=self.poly_cache.get(&poly){return self.find(*id);}let id=self.nodes.len().try_into().unwrap();self.nodes.push(Expr{kind,a,b,random:self.nodes[a as usize].random||self.nodes[b as usize].random});self.polys.push(poly.clone());self.poly_cache.insert(poly,id);self.parents.push(id);id}
 fn edge(&mut self,a:u32,b:u32,out:u32){let key=(a.min(b),a.max(b));if let Some(old)=self.xor_edges.get(&key){self.unite(*old,out);}else{self.xor_edges.insert(key,out);}}
 fn xor(&mut self,a:u32,b:u32)->u32{let a=self.find(a);let b=self.find(b);if a==b{return 0;}if a==0{return b;}if b==0{return a;}let key=(a.min(b),a.max(b));if let Some(id)=self.xor_edges.get(&key){return self.find(*id);}let aa=self.polys[a as usize].clone();let bb=self.polys[b as usize].clone();let atoms=Self::merge_xor(&aa.atoms,&bb.atoms);let result=self.reduce(aa.constant^bb.constant,atoms,3,a,b);if self.xor_edges.len()>500000{self.xor_edges.clear();}self.edge(a,b,result);self.edge(result,a,b);self.edge(result,b,a);self.find(result)}
 fn not(&mut self,a:u32)->u32{let a=self.find(a);if a==0{return 1;}if a==1{return 0;}let p=self.polys[a as usize].clone();let poly=std::sync::Arc::new(InputPoly{constant:!p.constant,atoms:p.atoms.clone()});if let Some(id)=self.poly_cache.get(&poly){return self.find(*id);}let id=self.nodes.len().try_into().unwrap();self.nodes.push(Expr{kind:3,a,b:1,random:self.nodes[a as usize].random});self.polys.push(poly.clone());self.poly_cache.insert(poly,id);self.parents.push(id);self.edge(a,1,id);self.edge(id,a,1);self.edge(id,1,a);id}
 fn multiply_monomials(&mut self,a:u32,b:u32)->u32{let mut key=self.monomials[a as usize].to_vec();key.extend_from_slice(&self.monomials[b as usize]);key.sort_unstable();key.dedup();if key.len()<=32{return self.mono(key);}let pair=(a.min(b),a.max(b));if let Some(id)=self.mono_products.get(&pair){return *id;}let random=key.iter().any(|id|self.nodes[*id as usize].random);let id=self.atomic(8,a,b,random);let m=self.polys[id as usize].atoms[0];self.mono_products.insert(pair,m);m}
 fn and(&mut self,a:u32,b:u32)->u32{let a=self.find(a);let b=self.find(b);if a==0||b==0||self.complementary(a,b){return 0;}if a==1{return b;}if b==1||a==b{return a;}if self.has_and_factor(a,b){return a;}if self.has_and_factor(b,a){return b;}let aa=self.polys[a as usize].clone();let bb=self.polys[b as usize].clone();let constant=aa.constant&&bb.constant;let mut terms=std::collections::BTreeSet::new();if aa.constant{for v in&bb.atoms{if !terms.insert(*v){terms.remove(v);}}}if bb.constant{for v in&aa.atoms{if !terms.insert(*v){terms.remove(v);}}}if aa.atoms.len()*bb.atoms.len()<=64{for x in&aa.atoms{for y in&bb.atoms{let m=self.multiply_monomials(*x,*y);if !terms.insert(m){terms.remove(&m);}}}}else{let(left,right)=if aa.atoms<=bb.atoms{(aa.atoms.clone(),bb.atoms.clone())}else{(bb.atoms.clone(),aa.atoms.clone())};let key=(left,right);let id=if let Some(id)=self.products.get(&key){*id}else{let ac=if aa.constant{self.not(a)}else{a};let bc=if bb.constant{self.not(b)}else{b};let id=self.atomic(4,ac,bc,self.nodes[ac as usize].random||self.nodes[bc as usize].random);if self.products.len()>=200000{self.products.clear();}self.products.insert(key,id);id};let m=self.polys[id as usize].atoms[0];if !terms.insert(m){terms.remove(&m);}}self.reduce(constant,terms.into_iter().collect(),4,a,b)}
}
